/// `tests/bugs/modalg_5/bug24532`
/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
#[should_panic]
fn bug24532() {
    expected_failure(|| {
        let mut d = Draw::new();
        d.polyline(&["w1", "-4", "-3", "0", "4", "-3", "0", "4", "3", "0", "-4", "3", "0", "-4", "-3", "0"])?;
        d.polyline(&["w2", "4", "3", "80", "-4", "3", "80", "-4", "-3", "80", "4", "-3", "80", "4", "3", "80"])?;
        d.polyline(&["sp", "0", "0", "0", "0", "0", "80"])?;
        d.cylinder(&["cc", "0", "0", "0", "0", "0", "1", "-4", "-3", "0", "5"])?;
        d.line(&["ll", "0", "0", "pi", "80"])?;
        d.trim(&["ll", "ll", "0", "sqrt(pi*pi+80*80)"])?;
        d.explode(&["w1", "v"])?;
        d.nearest(&["w1_1", "w1", "V", "-4.0", "-3.0", "0.0", "0.0"])?;
        d.explode(&["w2", "v"])?;
        d.nearest(&["w2_1", "w2", "V", "4.0", "3.0", "80.0", "0.0"])?;
        d.mkedge(&["ee", "ll", "cc", "w1_1", "w2_1"])?;
        d.wire(&["gg", "ee"])?;
        d.mksweep(&["sp"])?;
        d.setsweep(&["-G", "gg", "0", "0"])?;
        d.addsweep(&["w1"])?;
        d.buildsweep(&["result", "-S"])?;
        d.checkprops(&["result", "-s", "2343.46"])?;
        d.checkshape(&["result"])?;
        d.checknbshapes(&["result", "-vertex", "8", "-edge", "12", "-wire", "6", "-face", "6", "-shell", "1", "-solid", "1", "-compsolid", "0", "-compound", "0", "-shape", "34"])?;
        Ok(())
    })
}

