        d.explode(&["b2", "f"])?;
        d.nearest(&["b2_4", "b2", "F", "2.11913", "-2.07311", "0.999576", "153.164"])?;
        d.copy(&["b1_4", "b1"])?;
        d.copy(&["b2_4", "b2"])?;
